import Link from 'next/link';
import { getTranslations, translate, Language } from '@/lib/translations';

interface ProductsProps {
  params: Promise<{ lang: Language }>;
}

export default async function Products({ params }: ProductsProps) {
  const { lang } = await params;
  const translations = getTranslations(lang);
  const t = (key: string, params?: Record<string, string>) => 
    translate(translations, key, params);

  return (
    <main className="container mx-auto px-4 py-12">
      <div className="max-w-4xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-900 mb-8">{t('products.title')}</h1>
        <p className="text-lg text-gray-700 mb-12">
          {t('products.description')}
        </p>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <Link
            href={`/${lang}/products/potatoes`}
            className="bg-white border-2 border-green-700 rounded-lg p-6 hover:bg-green-50 transition-colors"
          >
            <h2 className="text-2xl font-semibold text-gray-900 mb-3">{t('products.potatoes.title')}</h2>
            <p className="text-gray-600">
              {t('products.potatoes.description')}
            </p>
          </Link>
          <Link
            href={`/${lang}/products/citrus`}
            className="bg-white border-2 border-green-700 rounded-lg p-6 hover:bg-green-50 transition-colors"
          >
            <h2 className="text-2xl font-semibold text-gray-900 mb-3">{t('products.citrus.title')}</h2>
            <p className="text-gray-600">
              {t('products.citrus.description')}
            </p>
          </Link>
        </div>
      </div>
    </main>
  );
}

